  T44: ['C', 'web/index.html declares <meta charset="UTF-8"> and the API always answers application/json; charset=UTF-8.', 'web/index.html declara <meta charset="UTF-8"> e a API sempre responde application/json; charset=UTF-8.'],
  T427: ['C', 'The database trigger track_sign_in keeps profiles.previous_sign_in_at; the app shows "Previous sign-in" after login and on the Profile screen.', 'O trigger track_sign_in mantém profiles.previous_sign_in_at; o app mostra "Previous sign-in" após o login e na tela de Perfil.'],
