  T2518: ['I', 'Post-development procedures not defined (see T2517).', 'Procedimentos pós-desenvolvimento não definidos (ver T2517).'],
  T2671: ['I', 'Commits and artifacts are not signed (see T1373).', 'Commits e artefatos não são assinados (ver T1373).'],
  T2672: ['I', 'Release signing not in place (see T1374).', 'Assinatura de releases não implementada (ver T1374).'],
  T2674: ['I', 'Supply-chain assessment not performed (see T1387).', 'Avaliação da cadeia de suprimentos não realizada (ver T1387).'],
  T2677: ['I', 'No per-release change summary (see T1378).', 'Sem resumo de mudanças por release (ver T1378).'],
  T2358: ['I', 'No PSIRT (see T2350).', 'Sem PSIRT (ver T2350).'],
  T2396: ['I', 'No incident plan (see T2392).', 'Sem plano de incidentes (ver T2392).'],
